import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { resolveMapAssetUrl } from "@/lib/maps/asset-url";
import { parseManifest } from "@/lib/maps/manifest";

const read = (p: string) => JSON.parse(readFileSync(resolve(__dirname, p), "utf8"));
// Generated by scripts/map-atlas (Python) from a synthetic client; guarded there by a byte-for-byte freshness test.
const atlasManifest = read("../../../scripts/map-atlas/tests/fixtures/sample-manifest.json");
const legacy = read("../../public/maps/forever/1420/v1/manifest.json");
// Generated by the atlas ZIP importer from a synthetic exporter archive (tests/test_importer.py keeps it byte-for-byte current).
const imported = read("../../../scripts/map-atlas/tests/fixtures/sample-atlas-manifest.json");

describe("map atlas <-> web manifest contract", () => {
  it("an atlas-exporter manifest is accepted by the web app's manifest loader", () => {
    const r = parseManifest(atlasManifest);
    expect(r.ok).toBe(true);
    if (r.ok) {
      expect(r.manifest.zoneId).toBe(atlasManifest.uiMapId);
      expect(r.manifest.calibration.status).toBe("provisional");
      expect(r.manifest.projection.origin).toBe("top-left");
      expect(r.manifest.image.format).toBe("webp");
    }
  });

  it("the legacy Tirisfal v1 manifest keeps validating (backward compatibility)", () => {
    expect(parseManifest(legacy).ok).toBe(true);
  });

  it("the CDN path the exporter writes is exactly what resolveMapAssetUrl builds", () => {
    const { zoneId, version, image } = atlasManifest;
    expect(resolveMapAssetUrl(undefined, zoneId, version, image.file)).toBe(`/maps/forever/${zoneId}/${version}/${image.file}`);
    expect(resolveMapAssetUrl("https://azerdex-assets.pages.dev", zoneId, version, "manifest.json")).toBe(`https://azerdex-assets.pages.dev/forever/${zoneId}/${version}/manifest.json`);
  });

  it("every file name the exporter can emit is accepted by the resolver", () => {
    for (const f of ["overview.webp", "layer-1.webp", "variant-7002.webp", "variant-7002-layer-1.webp", "manifest.json", "tirisfal-glades.webp"]) {
      expect(() => resolveMapAssetUrl(undefined, 1420, "v2", f)).not.toThrow();
    }
  });

  it("the exporter never marks calibration as validated on its own", () => {
    expect(atlasManifest.calibration.status).not.toBe("validated");
  });
});

describe("atlas ZIP importer manifests <-> web manifest contract", () => {
  it("an imported manifest (variants layout, default full-reveal) is accepted by the real parseManifest", () => {
    const r = parseManifest(imported);
    expect(r.ok).toBe(true);
    if (r.ok) {
      expect(r.manifest.zoneId).toBe(1420);
      expect(r.manifest.version).toBe("v2");
      expect(r.manifest.image.file).toBe("full-reveal.webp");
      expect(r.manifest.image.variant).toBe("full-reveal");
      expect(r.manifest.clientBuild?.version).toBe("1.60.1.70450");
      expect(r.manifest.calibration.status).toBe("provisional");
    }
  });

  it("the default image, and every variant image, resolves to a /forever/{uiMapID}/{version}/{file} URL", () => {
    const files = [imported.image.file, ...imported.variants.flatMap((v: { images: { file: string }[] }) => v.images.map((i) => i.file))];
    expect(new Set(files)).toEqual(new Set(["full-reveal.webp", "base.webp"]));
    for (const f of files) {
      expect(resolveMapAssetUrl("https://azerdex-assets.pages.dev", imported.zoneId, imported.version, f)).toBe(`https://azerdex-assets.pages.dev/forever/1420/v2/${f}`);
      expect(resolveMapAssetUrl("https://assets.azerdex.com", imported.zoneId, imported.version, f)).toBe(`https://assets.azerdex.com/forever/1420/v2/${f}`);
    }
  });

  it("the default image is one of the declared variants and the manifest says why", () => {
    const def = imported.variants.find((v: { isDefault: boolean }) => v.isDefault);
    expect(def.variant).toBe(imported.defaultImage.variant);
    expect(def.images.some((i: { file: string }) => i.file === imported.image.file)).toBe(true);
    expect(imported.defaultImage.reason).toMatch(/verified full-reveal/);
  });

  it("stays strict: a non-provisional/odd projection, bad file name or bad version is still rejected", () => {
    const bad = (mut: (m: typeof imported) => void) => { const m = structuredClone(imported); mut(m); return parseManifest(m).ok; };
    expect(bad((m) => { m.projection.origin = "bottom-left"; })).toBe(false);
    expect(bad((m) => { m.image.file = "../x.webp"; })).toBe(false);
    expect(bad((m) => { m.version = "latest"; })).toBe(false);
    expect(bad((m) => { m.image.variant = "Full Reveal!"; })).toBe(false);
  });
});

// Local-only: validates EVERY manifest of the real atlas distribution (private artwork, never in CI).
//   ATLAS_REAL_DIST=/path/to/out/dist npx vitest run tests/unit/map-atlas-contract.test.ts
const realDist = process.env.ATLAS_REAL_DIST;
const isFile = (p: string): boolean => statSync(p, { throwIfNoEntry: false })?.isFile() ?? false; // one call: no exists-then-stat race
describe.skipIf(!realDist || !isFile(join(realDist ?? "", "atlas/index.json")))("REAL atlas distribution (local acceptance)", () => {
  const dist = realDist ?? "";
  const manifests = (): { id: string; ver: string; m: any }[] => // eslint-disable-line @typescript-eslint/no-explicit-any
    readdirSync(join(dist, "forever")).flatMap((id) => readdirSync(join(dist, "forever", id)).map((ver) => ({ id, ver, m: JSON.parse(readFileSync(join(dist, "forever", id, ver, "manifest.json"), "utf8")) })));

  it("every published manifest passes parseManifest and every referenced file exists at its resolved CDN path", () => {
    const all = manifests();
    expect(all.length).toBe(61);
    for (const { id, ver, m } of all) {
      expect(parseManifest(m).ok, `${id}/${ver}`).toBe(true);
      expect(String(m.zoneId)).toBe(id);
      expect(m.version).toBe(ver);
      const files = [m.image.file, ...(m.variants ?? []).flatMap((v: any) => (v.images ?? []).map((i: any) => i.file))]; // eslint-disable-line @typescript-eslint/no-explicit-any
      for (const f of files) {
        const url = resolveMapAssetUrl("https://azerdex-assets.pages.dev", m.zoneId, m.version, f);
        const rel = url.replace("https://azerdex-assets.pages.dev/", "");
        const st = statSync(join(dist, rel), { throwIfNoEntry: false });
        expect(st?.isFile() === true && st.size > 0, rel).toBe(true);
      }
    }
  });

  it("the real index lists every manifest, and Tirisfal v1 (POC) is still the original asset", () => {
    const idx = JSON.parse(readFileSync(join(dist, "atlas/index.json"), "utf8"));
    expect(idx.maps.length).toBe(60);
    const t = idx.maps.find((e: { uiMapId: number }) => e.uiMapId === 1420);
    expect(t.versions).toEqual(["v1", "v2"]);
    expect(t.latestVersion).toBe("v2");
    expect(readFileSync(join(dist, "forever/1420/v1/tirisfal-glades.webp")).equals(readFileSync(resolve(__dirname, "../../public/maps/forever/1420/v1/tirisfal-glades.webp")))).toBe(true);
  });
});
